size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate, CompressionType compression, ExceptionInfo *exception) {
    size_t bytes_written = 0;
    unsigned char *compressed_pixels = NULL;
    size_t rows = image->rows;
    ssize_t row = 0;
    size_t bits_per_pixel = 8;
    MagickBooleanType status = MagickTrue;

    if (psd_info->monochrome) {
        bits_per_pixel = 1;
    }

    if (compression == RLECompression) {
        compressed_pixels = (unsigned char *) AcquireMemory(rows * image->columns * sizeof(*compressed_pixels));
        if (compressed_pixels == (unsigned char *) NULL) {
            ThrowBinaryException(ResourceLimitError, "MemoryAllocationFailed", image_info->filename);
            return 0;
        }

        for (row = 0; row < (ssize_t) rows; row++) {
            ExportPixels(next_image, 0, row, image->columns, 1, quantum_type, compact_pixels, exception);
            CompressRLE(compact_pixels, image->columns * bits_per_pixel, compressed_pixels + row * image->columns, &bytes_written);
        }
    }
    else if (compression == ZipCompression) {
        compressed_pixels = (unsigned char *) AcquireMemory(rows * image->columns * sizeof(*compressed_pixels));
        if (compressed_pixels == (unsigned char *) NULL) {
            ThrowBinaryException(ResourceLimitError, "MemoryAllocationFailed", image_info->filename);
            return 0;
        }

        for (row = 0; row < (ssize_t) rows; row++) {
            ExportPixels(next_image, 0, row, image->columns, 1, quantum_type, compact_pixels, exception);
            CompressZIP(compact_pixels, image->columns * bits_per_pixel, compressed_pixels + row * image->columns, &bytes_written);
        }
    }

    if (compressed_pixels != (unsigned char *) NULL) {
        status = WriteBlobMemory(image, size_offset, bytes_written, compressed_pixels);
        if (!status) {
            ThrowBinaryException(CoderError, "UnableToWritePSDChannel", image_info->filename);
        }
        compressed_pixels = (unsigned char *) RelinquishMemory(compressed_pixels);
    }

    return bytes_written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info,
                       Image *image, Image *next_image, QuantumType quantum_type,
                       unsigned char *compact_pixels, MagickOffsetType size_offset,
                       MagickBooleanType separate, CompressionType compression,
                       ExceptionInfo *exception) {
    size_t bytes_written = 0;
    size_t rows = 0;
    size_t row = 0;
    size_t row_size = 0;
    unsigned char *pixels = NULL;
    MagickBooleanType status = MagickTrue;

    if (image == (Image *) NULL)
        return 0;

    if (next_image == (Image *) NULL)
        return 0;

    if (compact_pixels == (unsigned char *) NULL)
        return 0;

    if ((compression != ZIPCompression) && (compression != RLECompression))
        compression = NoCompression;

    rows = image->rows;
    row_size = image->columns;

    pixels = (unsigned char *) AcquireMemory(row_size * sizeof(*pixels));
    if (pixels == (unsigned char *) NULL)
        return 0;

    for (row = 0; row < rows; row++) {
        status = ExportPixels(next_image, 0, row, next_image->columns, 1,
                              (char *) pixels, "Index", exception);
        if (!status)
            break;

        if (compression == RLECompression) {
            /* Apply RLE compression to the row */
            size_t compressed_size = CompressRLE(pixels, row_size, compact_pixels + bytes_written);
            if (compressed_size == 0) {
                status = MagickFalse;
                break;
            }
            bytes_written += compressed_size;
        }
        else if (compression == ZIPCompression) {
            /* Apply ZIP compression to the row */
            size_t compressed_size = CompressZIP(pixels, row_size, compact_pixels + bytes_written);
            if (compressed_size == 0) {
                status = MagickFalse;
                break;
            }
            bytes_written += compressed_size;
        }
        else {
            /* No compression, just copy pixels */
            (void) memcpy(compact_pixels + bytes_written, pixels, row_size);
            bytes_written += row_size;
        }
    }

    if (!status) {
        bytes_written = 0;
        if (pixels != (unsigned char *) NULL)
            pixels = RelinquishMemory(pixels);
    }

    pixels = RelinquishMemory(pixels);
    return bytes_written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate, CompressionType compression, ExceptionInfo *exception) {
    size_t bytes_written = 0;
    MagickBooleanType status = MagickFalse;
    unsigned char *rle_pixels = NULL;
    size_t rows = image->rows;
    size_t columns = image->columns;
    size_t depth = image->depth;
    size_t length = 0;
    ssize_t count = 0;
    size_t quantum_size = GetQuantumDepth(image);

    if (compression == RLECompression) {
        rle_pixels = (unsigned char *) AcquireMemory(rows * columns * sizeof(*rle_pixels));
        if (rle_pixels == (unsigned char *) NULL) {
            (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError, "MemoryAllocationFailed", "Unable to allocate memory for RLE pixels");
            goto cleanup;
        }
        for (size_t y = 0; y < rows; y++) {
            count = ExportImagePixels(image, 0, y, columns, 1, "RGB", quantum_type, rle_pixels + y * columns, exception);
            if (count != (ssize_t) (columns * quantum_size))
                goto cleanup;
        }
        length = RLECompress(rle_pixels, rows * columns * quantum_size, &compact_pixels);
    }
    else if (compression == ZipCompression) {
        length = ZIPCompress(compact_pixels, rows * columns * quantum_size);
    }

    if (length == 0) {
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "CorruptPSDImageFile", "Unable to compress PSD channel data");
        goto cleanup;
    }

    count = WriteBlobMSBLong(image, length);
    if ((size_t) count != sizeof(MagickSizeType))
        goto cleanup;

    count = WriteBlob(image, length, compact_pixels);
    if ((size_t) count != length)
        goto cleanup;

    bytes_written = (size_t) (length + sizeof(MagickSizeType));
    status = MagickTrue;

cleanup:
    if (rle_pixels != (unsigned char *) NULL)
        rle_pixels = (unsigned char *) RelinquishMemory(rle_pixels);
    return bytes_written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate, CompressionType compression, ExceptionInfo *exception) {
    size_t written = 0;
    ssize_t y;
    MagickBooleanType status;
    unsigned char *pixels = NULL;
    size_t length = image->columns * sizeof(Quantum);
    size_t count;

    for (y = 0; y < (ssize_t) image->rows; y++) {
        pixels = (unsigned char *) AcquireQuantumInfoPixels(image, (QuantumType *) compact_pixels, image->columns, 1, quantum_type, exception);
        if (pixels == (unsigned char *) NULL) {
            ThrowPSDException(PSDError, "UnableToWritePSDImage");
        }

        switch (compression) {
            case RLECompression:
                // RLE compression logic here
                break;
            case ZIPCompression:
                // ZIP compression logic here
                break;
            default:
                // Default to no compression
                break;
        }

        count = WriteBlobMemory(image, length, &length, pixels);
        written += count;

        if (count != length) {
            status = MagickFalse;
            break;
        }

        if (separate)
            continue;

        if (image_info->debug != MagickFalse)
            (void) fprintf(image_info->debug_file, "Writing PSD channel...\n");

        compact_pixels += length;
    }

    if (pixels != (unsigned char *) NULL)
        pixels = (unsigned char *) RelinquishMagickMemory(pixels);

    return written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate, CompressionType compression, ExceptionInfo *exception) {
    size_t count = 0;
    ssize_t y;
    unsigned char *pixels = NULL;

    for (y = 0; y < (ssize_t) image->rows; y++) {
        ExportPixelPacket(image, &pixels, image->columns);
        if (pixels == (unsigned char *) NULL) {
            ThrowPSDException(ResourceLimitError, "MemoryAllocationFailed", image_info);
            return 0;
        }

        switch (compression) {
            case RLECompression:
                pixels = RLECompress(pixels, image->columns, image->rows);
                break;
            case ZIPCompression:
                pixels = ZIPCompress(pixels, image->columns, image->rows);
                break;
            default:
                break;
        }

        count += WriteBlobMemory(image, size_offset, pixels, &count);
        MagickFree(pixels);
    }

    return count;
}
